function _drawSilhouette(ctx,type,x,baseY,fh,fw,variant){switch(type){case'conifers':ctx.lineTo(x-fw*0.5,baseY);ctx.lineTo(x-fw*0.4,baseY-fh*0.3);ctx.lineTo(x-fw*0.5,baseY-fh*0.28);ctx.lineTo(x-fw*0.3,baseY-fh*0.6);ctx.lineTo(x-fw*0.4,baseY-fh*0.58);ctx.lineTo(x,baseY-fh);ctx.lineTo(x+fw*0.4,baseY-fh*0.58);ctx.lineTo(x+fw*0.3,baseY-fh*0.6);ctx.lineTo(x+fw*0.5,baseY-fh*0.28);ctx.lineTo(x+fw*0.4,baseY-fh*0.3);ctx.lineTo(x+fw*0.5,baseY);break;case'deadTrees':ctx.lineTo(x-fw*0.1,baseY);ctx.lineTo(x-fw*0.08,baseY-fh*0.5);ctx.lineTo(x-fw*0.5,baseY-fh*0.8);ctx.lineTo(x-fw*0.35,baseY-fh*0.65);ctx.lineTo(x-fw*0.15,baseY-fh*0.7);ctx.lineTo(x-fw*0.3,baseY-fh*0.95);ctx.lineTo(x-fw*0.1,baseY-fh*0.75);ctx.lineTo(x,baseY-fh);ctx.lineTo(x+fw*0.1,baseY-fh*0.75);ctx.lineTo(x+fw*0.4,baseY-fh*0.9);ctx.lineTo(x+fw*0.2,baseY-fh*0.65);ctx.lineTo(x+fw*0.45,baseY-fh*0.7);ctx.lineTo(x+fw*0.08,baseY-fh*0.5);ctx.lineTo(x+fw*0.1,baseY);break;case'rocks':if(variant===0){ctx.lineTo(x-fw*0.6,baseY);ctx.lineTo(x-fw*0.5,baseY-fh*0.3);ctx.lineTo(x-fw*0.3,baseY-fh*0.7);ctx.lineTo(x-fw*0.1,baseY-fh);ctx.lineTo(x+fw*0.15,baseY-fh*0.6);ctx.lineTo(x+fw*0.3,baseY-fh*0.8);ctx.lineTo(x+fw*0.5,baseY-fh*0.35);ctx.lineTo(x+fw*0.6,baseY);}else if(variant===1){ctx.lineTo(x-fw*0.5,baseY);ctx.lineTo(x-fw*0.45,baseY-fh*0.5);ctx.lineTo(x-fw*0.2,baseY-fh*0.4);ctx.lineTo(x-fw*0.1,baseY-fh*0.9);ctx.lineTo(x+fw*0.1,baseY-fh);ctx.lineTo(x+fw*0.25,baseY-fh*0.5);ctx.lineTo(x+fw*0.4,baseY-fh*0.6);ctx.lineTo(x+fw*0.5,baseY);}else{ctx.lineTo(x-fw*0.4,baseY);ctx.lineTo(x-fw*0.35,baseY-fh*0.6);ctx.lineTo(x-fw*0.05,baseY-fh*0.85);ctx.lineTo(x+fw*0.2,baseY-fh);ctx.lineTo(x+fw*0.35,baseY-fh*0.55);ctx.lineTo(x+fw*0.4,baseY);}
break;case'dunes':ctx.lineTo(x-fw*0.8,baseY);ctx.quadraticCurveTo(x-fw*0.4,baseY-fh*0.7,x,baseY-fh*0.5);ctx.quadraticCurveTo(x+fw*0.3,baseY-fh*0.35,x+fw*0.5,baseY-fh*0.6);ctx.quadraticCurveTo(x+fw*0.7,baseY-fh*0.8,x+fw*0.9,baseY);break;case'peaks':ctx.lineTo(x-fw*0.7,baseY);ctx.lineTo(x-fw*0.5,baseY-fh*0.4);ctx.lineTo(x-fw*0.35,baseY-fh*0.35);ctx.lineTo(x-fw*0.2,baseY-fh*0.85);ctx.lineTo(x-fw*0.05,baseY-fh*0.7);ctx.lineTo(x+fw*0.1,baseY-fh);ctx.lineTo(x+fw*0.25,baseY-fh*0.6);ctx.lineTo(x+fw*0.4,baseY-fh*0.75);ctx.lineTo(x+fw*0.55,baseY-fh*0.3);ctx.lineTo(x+fw*0.7,baseY);break;case'tombstones':if(variant===0){ctx.lineTo(x-fw*0.2,baseY);ctx.lineTo(x-fw*0.2,baseY-fh*0.7);ctx.arc(x,baseY-fh*0.7,fw*0.2,Math.PI,0);ctx.lineTo(x+fw*0.2,baseY);}else if(variant===1){ctx.lineTo(x-fw*0.06,baseY);ctx.lineTo(x-fw*0.06,baseY-fh*0.55);ctx.lineTo(x-fw*0.25,baseY-fh*0.55);ctx.lineTo(x-fw*0.25,baseY-fh*0.7);ctx.lineTo(x-fw*0.06,baseY-fh*0.7);ctx.lineTo(x-fw*0.06,baseY-fh);ctx.lineTo(x+fw*0.06,baseY-fh);ctx.lineTo(x+fw*0.06,baseY-fh*0.7);ctx.lineTo(x+fw*0.25,baseY-fh*0.7);ctx.lineTo(x+fw*0.25,baseY-fh*0.55);ctx.lineTo(x+fw*0.06,baseY-fh*0.55);ctx.lineTo(x+fw*0.06,baseY);}else{ctx.lineTo(x-fw*0.15,baseY);ctx.lineTo(x-fw*0.15,baseY-fh*0.75);ctx.lineTo(x,baseY-fh);ctx.lineTo(x+fw*0.15,baseY-fh*0.75);ctx.lineTo(x+fw*0.15,baseY);}
break;case'hills':ctx.lineTo(x-fw*0.9,baseY);ctx.quadraticCurveTo(x-fw*0.4,baseY-fh*0.5,x,baseY-fh*0.4);ctx.quadraticCurveTo(x+fw*0.4,baseY-fh*0.25,x+fw*0.9,baseY);break;default:ctx.lineTo(x-fw,baseY);ctx.lineTo(x-fw*0.6,baseY-fh*0.4);ctx.lineTo(x-fw*0.2,baseY-fh);ctx.lineTo(x+fw*0.1,baseY-fh*0.85);ctx.lineTo(x+fw*0.5,baseY-fh*0.3);ctx.lineTo(x+fw,baseY);break;}}
function _drawGroundDetails(ctx,biome,w,h,groundY,elapsed){const scrollX=elapsed*0.08;const baseBiome=biome.startsWith('dungeon_')?biome.slice(8):biome;if(baseBiome==='swamp'){ctx.fillStyle='rgba(40,60,50,0.3)';for(let i=0;i<6;i++){const px=((i*80+20-scrollX)%(w+60))-30;ctx.beginPath();ctx.ellipse(px,groundY+20+i*8,25,5,0,0,Math.PI*2);ctx.fill();}}else if(baseBiome==='desert'){ctx.strokeStyle='rgba(200,180,120,0.15)';ctx.lineWidth=0.8;for(let i=0;i<10;i++){const rx=((i*50-scrollX*0.7)%(w+60))-30;ctx.beginPath();ctx.moveTo(rx,groundY+10);ctx.quadraticCurveTo(rx+15,groundY+6,rx+30,groundY+10);ctx.stroke();}}else if(baseBiome==='snow'){ctx.fillStyle='rgba(200,210,230,0.15)';for(let i=0;i<5;i++){const sx=((i*90+30-scrollX*0.5)%(w+80))-40;ctx.beginPath();ctx.ellipse(sx,groundY+15,35,6,0,0,Math.PI*2);ctx.fill();}}else if(baseBiome==='volcanic'){ctx.strokeStyle='rgba(255,80,0,0.3)';ctx.lineWidth=2;for(let i=0;i<4;i++){const lx=((i*110-scrollX*0.6)%(w+100))-50;ctx.beginPath();ctx.moveTo(lx,groundY+8);ctx.lineTo(lx+15,groundY+18);ctx.lineTo(lx+30,groundY+12);ctx.stroke();}}else if(baseBiome==='cave'){ctx.fillStyle='rgba(80,80,100,0.2)';for(let i=0;i<6;i++){const rx=((i*70+15-scrollX*0.4)%(w+60))-30;ctx.beginPath();ctx.moveTo(rx,groundY+5);ctx.lineTo(rx+5,groundY+2);ctx.lineTo(rx+10,groundY+4);ctx.lineTo(rx+8,groundY+8);ctx.lineTo(rx+2,groundY+8);ctx.closePath();ctx.fill();}}else if(baseBiome==='graveyard'){ctx.strokeStyle='rgba(100,100,80,0.2)';ctx.lineWidth=1;for(let i=0;i<6;i++){const gx=((i*65+10-scrollX*0.5)%(w+50))-25;ctx.beginPath();ctx.moveTo(gx,groundY+3);ctx.lineTo(gx-2,groundY-5);ctx.moveTo(gx+4,groundY+3);ctx.lineTo(gx+6,groundY-4);ctx.stroke();}}else if(baseBiome==='mountain'){ctx.fillStyle='rgba(120,110,100,0.2)';for(let i=0;i<8;i++){const mx=((i*50+8-scrollX*0.6)%(w+40))-20;ctx.beginPath();ctx.arc(mx,groundY+6+(i%3)*4,2+(i%2),0,Math.PI*2);ctx.fill();}}else{ctx.strokeStyle='rgba(80,120,40,0.25)';ctx.lineWidth=1.5;for(let i=0;i<8;i++){const gx=((i*55+10-scrollX)%(w+40))-20;ctx.beginPath();ctx.moveTo(gx,groundY+2);ctx.lineTo(gx-3,groundY-6);ctx.moveTo(gx+2,groundY+2);ctx.lineTo(gx+5,groundY-5);ctx.stroke();}}}
function _createTravelParticle(cfg,w,h){return{x:Math.random()*w*1.2-w*0.1,y:Math.random()*h,size:2+Math.random()*3,speed:10+Math.random()*20,phase:Math.random()*Math.PI*2,rotation:Math.random()*Math.PI*2,type:cfg.type,color:cfg.color,depth:0.4+Math.random()*0.6,};}
function _updateTravelParticles(ctx,particles,cfg,w,h,elapsed){const dt=0.016;for(const p of particles){const depthFactor=p.depth;const depthAlpha=0.3+depthFactor*0.7;const depthSize=0.5+depthFactor*0.5;switch(p.type){case'leaf':p.x-=p.speed*dt*2*depthFactor;p.y+=p.speed*dt*depthFactor;p.rotation+=dt*2;if(p.y>h||p.x<-20){p.x=w+20;p.y=Math.random()*h*0.6;}
ctx.save();ctx.globalAlpha=depthAlpha;ctx.translate(p.x,p.y);ctx.rotate(p.rotation);ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(0,0,p.size*depthSize,p.size*0.4*depthSize,0,0,Math.PI*2);ctx.fill();ctx.restore();break;case'snow':p.x+=Math.sin(elapsed*0.001+p.phase)*0.5*depthFactor;p.y+=p.speed*dt*depthFactor;if(p.y>h){p.y=-5;p.x=Math.random()*w;}
ctx.save();ctx.globalAlpha=depthAlpha;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*0.6*depthSize,0,Math.PI*2);ctx.fill();ctx.restore();break;case'ember':p.x+=(Math.random()-0.5)*2*depthFactor;p.y-=p.speed*dt*0.8*depthFactor;if(p.y<0){p.y=h*0.8+Math.random()*h*0.2;p.x=Math.random()*w;}
ctx.save();ctx.globalAlpha=depthAlpha;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*0.5*depthSize,0,Math.PI*2);ctx.fill();ctx.restore();break;case'wisp':p.x-=p.speed*dt*1.5*depthFactor;p.y+=Math.sin(elapsed*0.001+p.phase)*0.3;if(p.x<-30){p.x=w+30;p.y=h*0.5+Math.random()*h*0.3;}
ctx.save();ctx.globalAlpha=depthAlpha;ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(p.x,p.y,p.size*3*depthSize,p.size*depthSize,0,0,Math.PI*2);ctx.fill();ctx.restore();break;default:p.x-=p.speed*dt*0.3*depthFactor;if(p.x<-60){p.x=w+60;p.y=Math.random()*h;}
ctx.save();ctx.globalAlpha=depthAlpha;ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(p.x,p.y,p.size*8*depthSize,p.size*4*depthSize,0,0,Math.PI*2);ctx.fill();ctx.restore();break;}}}
function _drawTravelText(ctx,regionName,icon,w,h,alpha,drift){if(alpha<=0)return;ctx.save();ctx.globalAlpha=alpha;ctx.translate(0,-drift);ctx.font="700 22px 'Cinzel', 'MedievalSharp', serif";ctx.textAlign='center';ctx.fillStyle='#c4953a';ctx.shadowColor='rgba(0,0,0,0.9)';ctx.shadowBlur=10;ctx.fillText(regionName,w/2,h*0.22);ctx.shadowBlur=0;const dw=Math.min(180,ctx.measureText(regionName).width+40);const dy=h*0.25;ctx.strokeStyle='rgba(196,149,58,0.4)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w/2-dw/2,dy);ctx.lineTo(w/2-8,dy);ctx.stroke();ctx.beginPath();ctx.moveTo(w/2+8,dy);ctx.lineTo(w/2+dw/2,dy);ctx.stroke();ctx.fillStyle='rgba(196,149,58,0.5)';ctx.beginPath();ctx.moveTo(w/2,dy-3);ctx.lineTo(w/2+4,dy);ctx.lineTo(w/2,dy+3);ctx.lineTo(w/2-4,dy);ctx.closePath();ctx.fill();ctx.font="italic 13px 'MedievalSharp', 'Cinzel', serif";ctx.fillStyle='rgba(212,200,176,0.6)';ctx.shadowColor='rgba(0,0,0,0.6)';ctx.shadowBlur=4;ctx.fillText('Viajando...',w/2,h*0.29);ctx.restore();}
function _drawCelestial(ctx,w,h,elapsed,type){ctx.save();const drift=elapsed*0.003;if(_travelDetail<1){if(type==="moon"){const mx=w*0.78+drift,my=h*0.1;ctx.fillStyle="rgba(220,225,240,0.9)";ctx.beginPath();ctx.arc(mx,my,18,0,Math.PI*2);ctx.fill();ctx.fillStyle="rgba(15,15,25,0.92)";ctx.beginPath();ctx.arc(mx+8,my-3,15,0,Math.PI*2);ctx.fill();}else if(type==="sun"){const sx=w*0.8+drift,sy=h*0.12;ctx.fillStyle="rgba(255,230,150,0.85)";ctx.beginPath();ctx.arc(sx,sy,16,0,Math.PI*2);ctx.fill();}ctx.restore();return;}if(type==='moon'){const mx=w*0.78+drift,my=h*0.1;const r=18;const glow=ctx.createRadialGradient(mx,my,r*0.5,mx,my,r*4);glow.addColorStop(0,'rgba(200,210,230,0.12)');glow.addColorStop(0.5,'rgba(180,190,210,0.04)');glow.addColorStop(1,'rgba(180,190,210,0)');ctx.fillStyle=glow;ctx.fillRect(mx-r*4,my-r*4,r*8,r*8);ctx.fillStyle='rgba(220,225,240,0.9)';ctx.beginPath();ctx.arc(mx,my,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(15,15,25,0.92)';ctx.beginPath();ctx.arc(mx+r*0.45,my-r*0.15,r*0.85,0,Math.PI*2);ctx.fill();}else if(type==='sun'){const sx=w*0.8+drift,sy=h*0.12;const r=16;const glow=ctx.createRadialGradient(sx,sy,r*0.3,sx,sy,r*5);glow.addColorStop(0,'rgba(255,220,120,0.18)');glow.addColorStop(0.3,'rgba(255,200,80,0.08)');glow.addColorStop(0.7,'rgba(255,180,60,0.02)');glow.addColorStop(1,'rgba(255,180,60,0)');ctx.fillStyle=glow;ctx.fillRect(sx-r*5,sy-r*5,r*10,r*10);ctx.fillStyle='rgba(255,230,150,0.85)';ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(255,245,200,0.5)';ctx.beginPath();ctx.arc(sx,sy,r*0.5,0,Math.PI*2);ctx.fill();}
ctx.restore();}
function _generateShootingStars(w,h){const count=1+Math.floor(Math.random()*2);const stars=[];for(let i=0;i<count;i++){stars.push({startX:w*0.2+Math.random()*w*0.6,startY:Math.random()*h*0.25,angle:0.4+Math.random()*0.4,speed:280+Math.random()*120,length:40+Math.random()*30,triggerTime:800+Math.random()*2200,duration:350+Math.random()*200,});}
return stars;}
function _drawShootingStars(ctx,shootingStars,elapsed){if(_travelDetail<1)return;for(const s of shootingStars){const t=elapsed-s.triggerTime;if(t<0||t>s.duration)continue;const progress=t/s.duration;const alpha=progress<0.3?progress/0.3:1-((progress-0.3)/0.7);const dist=progress*s.speed;const dx=Math.cos(s.angle)*dist;const dy=Math.sin(s.angle)*dist;const headX=s.startX+dx;const headY=s.startY+dy;const tailX=headX-Math.cos(s.angle)*s.length;const tailY=headY-Math.sin(s.angle)*s.length;const grad=ctx.createLinearGradient(tailX,tailY,headX,headY);grad.addColorStop(0,`rgba(255,255,240,0)`);grad.addColorStop(0.7,`rgba(255,255,240,${alpha * 0.4})`);grad.addColorStop(1,`rgba(255,255,255,${alpha * 0.9})`);ctx.strokeStyle=grad;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(tailX,tailY);ctx.lineTo(headX,headY);ctx.stroke();ctx.fillStyle=`rgba(255,255,255,${alpha * 0.8})`;ctx.beginPath();ctx.arc(headX,headY,1.5,0,Math.PI*2);ctx.fill();}}
function _generateClouds(w,h,type){const clouds=[];let count,yRange,alphaBase,sizeBase;switch(type){case'thin':count=3;yRange=[0.05,0.2];alphaBase=0.06;sizeBase=60;break;case'heavy':count=5;yRange=[0.03,0.25];alphaBase=0.12;sizeBase=80;break;case'dark':count=4;yRange=[0.05,0.22];alphaBase=0.10;sizeBase=70;break;case'fog':count=5;yRange=[0.20,0.45];alphaBase=0.07;sizeBase=100;break;case'smoke':count=4;yRange=[0.10,0.35];alphaBase=0.10;sizeBase=70;break;default:count=3;yRange=[0.05,0.2];alphaBase=0.06;sizeBase=60;break;}
for(let i=0;i<count;i++){const depth=0.3+Math.random()*0.7;clouds.push({x:Math.random()*w*1.5-w*0.25,y:h*(yRange[0]+Math.random()*(yRange[1]-yRange[0])),w:sizeBase+Math.random()*sizeBase*0.8,h:8+Math.random()*12,alpha:alphaBase+Math.random()*alphaBase*0.5,depth:depth,type:type,});}
return clouds;}
function _drawClouds(ctx,clouds,canvasW,elapsed){ctx.save();for(const c of clouds){const speed=0.008*c.depth;const cx=((c.x-elapsed*speed)%(canvasW+c.w*2));const drawX=cx<-c.w?cx+canvasW+c.w*2:cx;let color;if(c.type==='smoke'){color=`rgba(80,40,20,${c.alpha})`;}else if(c.type==='dark'){color=`rgba(30,30,40,${c.alpha})`;}else if(c.type==='fog'){color=`rgba(140,150,130,${c.alpha})`;}else{color=`rgba(200,200,210,${c.alpha})`;}
ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(drawX,c.y,c.w*0.5,c.h,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(drawX-c.w*0.2,c.y+c.h*0.3,c.w*0.35,c.h*0.7,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(drawX+c.w*0.25,c.y-c.h*0.2,c.w*0.3,c.h*0.8,0,0,Math.PI*2);ctx.fill();}
ctx.restore();}
function _drawVignette(ctx,w,h){if(_travelDetail<1)return;const cx=w/2,cy=h/2;const outerR=Math.sqrt(cx*cx+cy*cy);const grad=ctx.createRadialGradient(cx,cy,outerR*0.45,cx,cy,outerR);grad.addColorStop(0,'rgba(0,0,0,0)');grad.addColorStop(0.7,'rgba(0,0,0,0)');grad.addColorStop(1,'rgba(0,0,0,0.35)');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);}
function _generateFireflies(w,h){const flies=[];const groundY=h*0.72;for(let i=0;i<12;i++){flies.push({x:Math.random()*w,y:groundY-30-Math.random()*200,baseX:Math.random()*w,baseY:groundY-30-Math.random()*200,phase:Math.random()*Math.PI*2,speed:0.5+Math.random()*1.0,size:1.5+Math.random()*1.5,glowPhase:Math.random()*Math.PI*2,});}
return flies;}
function _drawFireflies(ctx,flies,elapsed){if(_travelDetail<1)return;for(const f of flies){f.x=f.baseX+Math.sin(elapsed*0.0008*f.speed+f.phase)*40;f.y=f.baseY+Math.cos(elapsed*0.0006*f.speed+f.phase*1.5)*25;const glow=Math.max(0,Math.sin(elapsed*0.003*f.speed+f.glowPhase));if(glow<0.15)continue;const alpha=glow*0.8;const grad=ctx.createRadialGradient(f.x,f.y,0,f.x,f.y,f.size*6);grad.addColorStop(0,`rgba(180,200,60,${alpha * 0.4})`);grad.addColorStop(0.5,`rgba(150,180,40,${alpha * 0.15})`);grad.addColorStop(1,'rgba(150,180,40,0)');ctx.fillStyle=grad;ctx.fillRect(f.x-f.size*6,f.y-f.size*6,f.size*12,f.size*12);ctx.fillStyle=`rgba(220,240,100,${alpha})`;ctx.beginPath();ctx.arc(f.x,f.y,f.size,0,Math.PI*2);ctx.fill();}}
function _generateLightning(){const flashes=[];const count=1+Math.floor(Math.random()*2);for(let i=0;i<count;i++){flashes.push({triggerTime:1000+Math.random()*2000,duration:300,});}
return flashes;}
function _drawLightning(ctx,flashes,w,h,elapsed){for(const f of flashes){const t=elapsed-f.triggerTime;if(t<0||t>f.duration)continue;let alpha;if(t<40){alpha=0.25;}else if(t<80){alpha=0.08;}else if(t<120){alpha=0.18;}else{alpha=0.18*Math.max(0,1-(t-120)/180);}
ctx.fillStyle=`rgba(200,200,240,${alpha})`;ctx.fillRect(0,0,w,h);}}
function _generateFauna(w,h,type){const group=[];const count=type==='bat'?4+Math.floor(Math.random()*3):3+Math.floor(Math.random()*3);const baseX=-40-Math.random()*60;const baseY=h*0.08+Math.random()*h*0.2;const triggerTime=500+Math.random()*2000;for(let i=0;i<count;i++){group.push({offsetX:i*(12+Math.random()*8),offsetY:(Math.random()-0.5)*20,wingPhase:Math.random()*Math.PI*2,wingSpeed:type==='bat'?12+Math.random()*4:5+Math.random()*2,size:type==='bat'?3+Math.random()*2:2.5+Math.random()*1.5,type:type,});}
return[{members:group,baseX,baseY,speed:type==='bat'?80:50,triggerTime}];}
function _drawFauna(ctx,faunaGroups,canvasW,elapsed){for(const g of faunaGroups){const t=elapsed-g.triggerTime;if(t<0)continue;const groupX=g.baseX+t*g.speed*0.001;if(groupX>canvasW+100)continue;for(const m of g.members){const x=groupX+m.offsetX;const y=g.baseY+m.offsetY+Math.sin(t*0.002+m.wingPhase)*5;const wingAngle=Math.sin(t*0.001*m.wingSpeed+m.wingPhase);const s=m.size;ctx.save();ctx.translate(x,y);ctx.fillStyle=m.type==='bat'?'rgba(20,15,25,0.7)':'rgba(40,35,30,0.6)';if(m.type==='bat'){const wingSpan=s*2.5;const wingY=wingAngle*s*0.8;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-wingSpan,wingY);ctx.lineTo(-wingSpan*0.6,wingY*0.3);ctx.lineTo(-wingSpan*0.3,wingY*0.7);ctx.lineTo(0,0);ctx.lineTo(wingSpan*0.3,wingY*0.7);ctx.lineTo(wingSpan*0.6,wingY*0.3);ctx.lineTo(wingSpan,wingY);ctx.closePath();ctx.fill();}else{const wingSpan=s*2;const wingY=wingAngle*s*0.6;ctx.beginPath();ctx.moveTo(-wingSpan,wingY);ctx.quadraticCurveTo(-wingSpan*0.3,wingY*0.2,0,s*0.3);ctx.quadraticCurveTo(wingSpan*0.3,wingY*0.2,wingSpan,wingY);ctx.lineWidth=1.2;ctx.strokeStyle=ctx.fillStyle;ctx.stroke();}
ctx.restore();}}}
function _drawHeatShimmer(ctx,w,groundY,elapsed){const bandH=30;const bandY=groundY-bandH;ctx.save();ctx.globalAlpha=0.04;for(let i=0;i<5;i++){const waveOffset=Math.sin(elapsed*0.002+i*1.2)*8;const y=bandY+i*6+waveOffset;ctx.fillStyle='rgba(255,255,255,1)';ctx.beginPath();ctx.moveTo(0,y);for(let x=0;x<=w;x+=20){const wy=y+Math.sin(x*0.03+elapsed*0.003+i)*3;ctx.lineTo(x,wy);}
ctx.lineTo(w,y+4);ctx.lineTo(0,y+4);ctx.closePath();ctx.fill();}
ctx.restore();}
function _drawAurora(ctx,w,h,elapsed){if(_travelDetail<1)return;ctx.save();const skyH=h*0.35;const bands=[{color:[80,200,120],yBase:0.12,amplitude:15,freq:0.008,speed:0.0004,alpha:0.06},{color:[100,140,220],yBase:0.18,amplitude:20,freq:0.006,speed:0.0005,alpha:0.04},{color:[160,80,200],yBase:0.08,amplitude:12,freq:0.01,speed:0.0003,alpha:0.035},];for(const b of bands){const baseY=skyH*b.yBase;ctx.beginPath();ctx.moveTo(0,h);for(let x=0;x<=w;x+=5){const y=baseY+Math.sin(x*b.freq+elapsed*b.speed)*b.amplitude
+Math.sin(x*b.freq*2.3+elapsed*b.speed*1.5)*b.amplitude*0.4;ctx.lineTo(x,y);}
for(let x=w;x>=0;x-=5){const y=baseY+40+Math.sin(x*b.freq*0.8+elapsed*b.speed*0.7)*b.amplitude*0.6;ctx.lineTo(x,y);}
ctx.closePath();const grad=ctx.createLinearGradient(0,baseY,0,baseY+50);grad.addColorStop(0,`rgba(${b.color.join(',')},${b.alpha})`);grad.addColorStop(0.5,`rgba(${b.color.join(',')},${b.alpha * 0.5})`);grad.addColorStop(1,`rgba(${b.color.join(',')},0)`);ctx.fillStyle=grad;ctx.fill();}
ctx.restore();}
function _drawLavaGlow(ctx,w,groundY,elapsed){if(_travelDetail<1)return;const pulse=0.5+0.5*Math.sin(elapsed*0.002);const alpha=0.04+pulse*0.04;const glowH=60;const grad=ctx.createLinearGradient(0,groundY+10,0,groundY-glowH);grad.addColorStop(0,`rgba(255,60,0,${alpha})`);grad.addColorStop(0.4,`rgba(255,40,0,${alpha * 0.5})`);grad.addColorStop(1,'rgba(255,40,0,0)');ctx.fillStyle=grad;ctx.fillRect(0,groundY-glowH,w,glowH+10);const scrollX=elapsed*0.08;ctx.save();for(let i=0;i<4;i++){const lx=((i*110-scrollX*0.6)%(w+100))-50;const spotAlpha=0.08+pulse*0.06;const spot=ctx.createRadialGradient(lx+15,groundY+5,0,lx+15,groundY+5,25);spot.addColorStop(0,`rgba(255,80,0,${spotAlpha})`);spot.addColorStop(1,'rgba(255,80,0,0)');ctx.fillStyle=spot;ctx.fillRect(lx-10,groundY-20,50,40);}
ctx.restore();}
function _drawWaterReflections(ctx,w,_h,groundY,elapsed){const scrollX=elapsed*0.08;ctx.save();for(let i=0;i<4;i++){const px=((i*120+40-scrollX*0.6)%(w+140))-70;const py=groundY+12+i*14;const pw=50+(i%2)*20;const ph=6+(i%2)*2;ctx.fillStyle='rgba(20,40,35,0.3)';ctx.beginPath();ctx.ellipse(px,py,pw,ph,0,0,Math.PI*2);ctx.fill();const rippleCount=3;for(let r=0;r<rippleCount;r++){const ripplePhase=elapsed*0.003+r*2.1+i;const rippleX=px+Math.sin(ripplePhase)*pw*0.4;const rippleAlpha=0.08+0.06*Math.sin(ripplePhase*1.5);ctx.strokeStyle=`rgba(140,180,160,${rippleAlpha})`;ctx.lineWidth=0.6;ctx.beginPath();ctx.ellipse(rippleX,py,8+r*4,1.5,0,0,Math.PI*2);ctx.stroke();}
const reflAlpha=0.06+0.03*Math.sin(elapsed*0.002+i);ctx.fillStyle=`rgba(60,80,60,${reflAlpha})`;ctx.beginPath();ctx.ellipse(px,py-1,pw*0.6,ph*0.5,0,0,Math.PI*2);ctx.fill();}
ctx.restore();}
function _drawGodRays(ctx,w,h,elapsed,celestialType){if(_travelDetail<1)return;const isSun=celestialType==='sun';const drift=elapsed*0.003;const srcX=w*0.78+drift;const srcY=isSun?h*0.12:h*0.1;const rayColor=isSun?[255,220,120]:[180,190,220];const rayCount=5;const baseAlpha=isSun?0.025:0.012;ctx.save();for(let i=0;i<rayCount;i++){const angleBase=-0.3+(i/(rayCount-1))*0.9;const angleWobble=Math.sin(elapsed*0.0005+i*1.7)*0.08;const angle=angleBase+angleWobble;const rayLen=h*0.8;const endX=srcX+Math.sin(angle)*rayLen;const endY=srcY+Math.cos(angle*0.3+0.7)*rayLen;const pulse=0.6+0.4*Math.sin(elapsed*0.001+i*2.3);const alpha=baseAlpha*pulse;const grad=ctx.createLinearGradient(srcX,srcY,endX,endY);grad.addColorStop(0,`rgba(${rayColor.join(',')},${alpha * 1.5})`);grad.addColorStop(0.3,`rgba(${rayColor.join(',')},${alpha})`);grad.addColorStop(1,`rgba(${rayColor.join(',')},0)`);ctx.fillStyle=grad;ctx.beginPath();const spread=3+i*2;const endSpread=30+i*15;ctx.moveTo(srcX-spread,srcY);ctx.lineTo(endX-endSpread,endY);ctx.lineTo(endX+endSpread,endY);ctx.lineTo(srcX+spread,srcY);ctx.closePath();ctx.fill();}
ctx.restore();}
function _generateDustMotes(w,h){const motes=[];for(let i=0;i<20;i++){motes.push({x:Math.random()*w,y:Math.random()*h*0.7,size:0.5+Math.random()*1.2,driftX:(Math.random()-0.3)*0.3,driftY:(Math.random()-0.5)*0.15,phase:Math.random()*Math.PI*2,brightness:0.3+Math.random()*0.7,twinkleSpeed:1.5+Math.random()*2.5,});}
return motes;}
function _drawDustMotes(ctx,motes,w,h,elapsed){if(_travelDetail<1)return;ctx.save();for(const m of motes){m.x+=m.driftX;m.y+=m.driftY+Math.sin(elapsed*0.001+m.phase)*0.08;if(m.x>w+5)m.x=-5;if(m.x<-5)m.x=w+5;if(m.y>h*0.72){m.y=-2;m.x=Math.random()*w;}
if(m.y<-5)m.y=h*0.7;const twinkle=m.brightness*(0.3+0.7*Math.max(0,Math.sin(elapsed*0.001*m.twinkleSpeed+m.phase)));if(twinkle<0.1)continue;const grad=ctx.createRadialGradient(m.x,m.y,0,m.x,m.y,m.size*3);grad.addColorStop(0,`rgba(255,240,180,${twinkle * 0.5})`);grad.addColorStop(0.5,`rgba(255,220,140,${twinkle * 0.15})`);grad.addColorStop(1,'rgba(255,220,140,0)');ctx.fillStyle=grad;ctx.fillRect(m.x-m.size*3,m.y-m.size*3,m.size*6,m.size*6);ctx.fillStyle=`rgba(255,250,200,${twinkle * 0.7})`;ctx.beginPath();ctx.arc(m.x,m.y,m.size*0.5,0,Math.PI*2);ctx.fill();}
ctx.restore();}
function _drawAtmosphericHaze(ctx,w,h,yRatio,skyColor,alpha){if(_travelDetail<1)return;const baseY=h*yRatio;const hazeH=h*0.2;const r=parseInt(skyColor.slice(1,3),16);const g=parseInt(skyColor.slice(3,5),16);const b=parseInt(skyColor.slice(5,7),16);const grad=ctx.createLinearGradient(0,baseY-hazeH*0.3,0,baseY+hazeH);grad.addColorStop(0,`rgba(${r},${g},${b},${alpha * 0.6})`);grad.addColorStop(0.4,`rgba(${r},${g},${b},${alpha})`);grad.addColorStop(1,`rgba(${r},${g},${b},${alpha * 0.3})`);ctx.fillStyle=grad;ctx.fillRect(0,baseY-hazeH*0.3,w,hazeH*1.3);}
function _generateVegetation(w,_h,biome){const veg=[];const baseBiome=biome.startsWith('dungeon_')?biome.slice(8):biome;const count=18+Math.floor(Math.random()*8);for(let i=0;i<count;i++){let type;if(baseBiome==='swamp'){type=Math.random()<0.4?'cattail':'reed';}else if(baseBiome==='plains'){type=Math.random()<0.3?'flower':'grass';}else{type=Math.random()<0.15?'fern':'grass';}
veg.push({x:Math.random()*w*2,height:6+Math.random()*10,type:type,phase:Math.random()*Math.PI*2,swaySpeed:0.8+Math.random()*1.2,color:baseBiome==='plains'?`rgba(${100 + Math.floor(Math.random() * 40)},${120 + Math.floor(Math.random() * 30)},40,0.5)`:`rgba(${50 + Math.floor(Math.random() * 30)},${80 + Math.floor(Math.random() * 30)},30,0.4)`,});}
return veg;}
function _drawVegetation(ctx,veg,w,groundY,elapsed){const scrollX=elapsed*0.08;ctx.save();for(const v of veg){const x=((v.x-scrollX)%(w*2)+w*2)%(w*2)-w*0.1;if(x<-20||x>w+20)continue;const sway=Math.sin(elapsed*0.002*v.swaySpeed+v.phase)*3;const baseY=groundY+2;ctx.strokeStyle=v.color;ctx.lineWidth=1.2;if(v.type==='grass'){ctx.beginPath();ctx.moveTo(x,baseY);ctx.quadraticCurveTo(x+sway*0.5,baseY-v.height*0.5,x+sway,baseY-v.height);ctx.stroke();ctx.beginPath();ctx.moveTo(x+2,baseY);ctx.quadraticCurveTo(x+2+sway*0.3,baseY-v.height*0.4,x+3+sway*0.7,baseY-v.height*0.8);ctx.stroke();}else if(v.type==='cattail'){ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x,baseY);ctx.quadraticCurveTo(x+sway*0.3,baseY-v.height*0.6,x+sway*0.5,baseY-v.height*1.3);ctx.stroke();ctx.fillStyle='rgba(80,50,20,0.5)';ctx.beginPath();ctx.ellipse(x+sway*0.5,baseY-v.height*1.3,1.5,4,0,0,Math.PI*2);ctx.fill();}else if(v.type==='reed'){ctx.lineWidth=0.8;ctx.beginPath();ctx.moveTo(x,baseY);ctx.lineTo(x+sway,baseY-v.height);ctx.stroke();}else if(v.type==='flower'){ctx.strokeStyle='rgba(60,100,30,0.5)';ctx.beginPath();ctx.moveTo(x,baseY);ctx.quadraticCurveTo(x+sway*0.4,baseY-v.height*0.5,x+sway*0.6,baseY-v.height);ctx.stroke();const colors=['rgba(200,80,80,0.6)','rgba(220,180,60,0.6)','rgba(180,100,200,0.6)','rgba(240,240,100,0.6)'];ctx.fillStyle=colors[Math.floor(v.phase)%colors.length];ctx.beginPath();ctx.arc(x+sway*0.6,baseY-v.height,1.5,0,Math.PI*2);ctx.fill();}else if(v.type==='fern'){ctx.lineWidth=0.8;ctx.beginPath();ctx.moveTo(x,baseY);ctx.quadraticCurveTo(x+sway,baseY-v.height*0.6,x+sway*1.5,baseY-v.height*0.4);ctx.stroke();ctx.beginPath();ctx.moveTo(x,baseY);ctx.quadraticCurveTo(x-sway*0.5,baseY-v.height*0.5,x-sway,baseY-v.height*0.3);ctx.stroke();}}
ctx.restore();}
function _drawTerrainRimLight(ctx,features,w,h,yRatio,offset,silhouetteType,celestialType,intensity){const baseY=h*yRatio;const isSun=celestialType==='sun';const rimColor=isSun?'255,220,140':'180,190,230';const alpha=(isSun?0.15:0.08)*intensity;ctx.save();ctx.strokeStyle=`rgba(${rimColor},${alpha})`;ctx.lineWidth=1.2;ctx.beginPath();for(const f of features){const x=((f.x-offset)%(w*2)+w*2)%(w*2)-w*0.3;const fh=f.height*h*0.18;const fw=f.width*40;if(silhouetteType==='conifers'){ctx.moveTo(x,baseY-fh);ctx.lineTo(x+fw*0.4,baseY-fh*0.58);ctx.lineTo(x+fw*0.5,baseY);}else if(silhouetteType==='peaks'){ctx.moveTo(x+fw*0.1,baseY-fh);ctx.lineTo(x+fw*0.4,baseY-fh*0.75);ctx.lineTo(x+fw*0.7,baseY);}else if(silhouetteType==='deadTrees'){ctx.moveTo(x,baseY-fh);ctx.lineTo(x+fw*0.4,baseY-fh*0.9);ctx.lineTo(x+fw*0.08,baseY-fh*0.5);}else{ctx.moveTo(x-fw*0.1,baseY-fh);ctx.lineTo(x+fw*0.5,baseY-fh*0.35);ctx.lineTo(x+fw*0.6,baseY);}}
ctx.stroke();ctx.restore();}
function _drawLightningBolts(ctx,flashes,w,h,elapsed){for(const f of flashes){const t=elapsed-f.triggerTime;if(t<0||t>f.duration*0.6)continue;let alpha;if(t<40)alpha=0.7;else if(t<80)alpha=0.15;else if(t<120)alpha=0.5;else alpha=0.5*Math.max(0,1-(t-120)/80);if(alpha<0.05)continue;const seed=f.triggerTime;const boltX=w*0.3+(seed%100)/100*w*0.4;ctx.save();ctx.strokeStyle=`rgba(200,200,255,${alpha})`;ctx.lineWidth=2;ctx.shadowColor=`rgba(150,150,255,${alpha * 0.8})`;ctx.shadowBlur=8;ctx.beginPath();let bx=boltX,by=0;ctx.moveTo(bx,by);const segments=8+((seed*7)%5);const endY=h*0.45+(seed%50);const segH=endY/segments;for(let i=0;i<segments;i++){bx+=((seed*(i+3)*13)%40)-20;by+=segH;ctx.lineTo(bx,by);if(i===Math.floor(segments*0.3)||i===Math.floor(segments*0.6)){const branchDir=(i%2===0)?1:-1;const branchLen=20+(seed%30);ctx.moveTo(bx,by);ctx.lineTo(bx+branchLen*branchDir,by+branchLen*0.6);ctx.moveTo(bx,by);}}
ctx.stroke();ctx.restore();}}
function _generateFogBands(w,_h){const bands=[];for(let group=0;group<2;group++){const count=2+Math.floor(Math.random()*2);for(let i=0;i<count;i++){bands.push({group,x:Math.random()*w*2-w*0.5,yOffset:(Math.random()-0.5)*15,width:100+Math.random()*120,height:4+Math.random()*6,alpha:0.04+Math.random()*0.04,speed:0.005+Math.random()*0.008,phase:Math.random()*Math.PI*2,});}}
return bands;}
function _drawFogBands(ctx,bands,w,h,elapsed,group){const baseY=group===0?h*0.47:h*0.62;ctx.save();for(const b of bands){if(b.group!==group)continue;const drift=elapsed*b.speed;const bx=((b.x-drift)%(w+b.width*2));const drawX=bx<-b.width?bx+w+b.width*2:bx;const by=baseY+b.yOffset+Math.sin(elapsed*0.001+b.phase)*4;ctx.fillStyle=`rgba(180,190,170,${b.alpha})`;ctx.beginPath();ctx.ellipse(drawX,by,b.width*0.5,b.height,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=`rgba(180,190,170,${b.alpha * 0.5})`;ctx.beginPath();ctx.ellipse(drawX+b.width*0.2,by+2,b.width*0.3,b.height*0.6,0,0,Math.PI*2);ctx.fill();}
ctx.restore();}
function _drawSnowCaps(ctx,features,w,h,yRatio,offset,silhouetteType,intensity){if(silhouetteType!=='peaks')return;const baseY=h*yRatio;ctx.save();ctx.fillStyle=`rgba(230,235,245,${0.3 * intensity})`;for(const f of features){const x=((f.x-offset)%(w*2)+w*2)%(w*2)-w*0.3;const fh=f.height*h*0.18;const fw=f.width*40;const capH=fh*0.2;ctx.beginPath();ctx.moveTo(x+fw*0.1,baseY-fh);ctx.lineTo(x+fw*0.1-fw*0.12,baseY-fh+capH);ctx.lineTo(x+fw*0.1+fw*0.15,baseY-fh+capH);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(x+fw*0.4,baseY-fh*0.75);ctx.lineTo(x+fw*0.4-fw*0.08,baseY-fh*0.75+capH*0.7);ctx.lineTo(x+fw*0.4+fw*0.1,baseY-fh*0.75+capH*0.7);ctx.closePath();ctx.fill();}
ctx.restore();}
function _generateFallingLeaves(w,_h,type){const leaves=[];const count=type==='dead'?6:8;for(let i=0;i<count;i++){leaves.push({x:Math.random()*w,y:-10-Math.random()*200,size:2+Math.random()*2.5,rotation:Math.random()*Math.PI*2,rotSpeed:2+Math.random()*3,fallSpeed:15+Math.random()*20,swayAmp:20+Math.random()*30,swayFreq:1+Math.random()*1.5,phase:Math.random()*Math.PI*2,type,spawnTime:Math.random()*2500,});}
return leaves;}
function _drawFallingLeaves(ctx,leaves,w,h,elapsed){const groundY=h*0.72;for(const l of leaves){if(elapsed<l.spawnTime)continue;const t=(elapsed-l.spawnTime)*0.001;l.y=-10+t*l.fallSpeed;l.x+=Math.sin(t*l.swayFreq+l.phase)*l.swayAmp*0.01;l.rotation+=l.rotSpeed*0.016;if(l.y>groundY+10){l.y=-10;l.x=Math.random()*w;l.spawnTime=elapsed+Math.random()*500;}
if(l.y<-15)continue;ctx.save();ctx.translate(l.x,l.y);ctx.rotate(l.rotation);if(l.type==='dead'){ctx.fillStyle=`rgba(${120 + Math.floor(l.phase * 20)},${70 + Math.floor(l.phase * 10)},20,0.5)`;ctx.beginPath();ctx.ellipse(0,0,l.size,l.size*0.5,0,0,Math.PI*2);ctx.fill();}else{ctx.fillStyle=`rgba(${60 + Math.floor(l.phase * 15)},${120 + Math.floor(l.phase * 10)},30,0.5)`;ctx.beginPath();ctx.moveTo(0,-l.size);ctx.quadraticCurveTo(l.size*0.8,-l.size*0.2,0,l.size);ctx.quadraticCurveTo(-l.size*0.8,-l.size*0.2,0,-l.size);ctx.fill();}
ctx.restore();}}
function _drawCelestialReflection(ctx,w,groundY,elapsed,celestialType){if(_travelDetail<1)return;const isSun=celestialType==='sun';const drift=elapsed*0.003;const srcX=w*0.78+drift;const reflX=Math.min(w*0.7,Math.max(w*0.2,srcX-w*0.1));const reflY=groundY+25;const baseAlpha=isSun?0.12:0.06;const pulse=0.7+0.3*Math.sin(elapsed*0.003);const alpha=baseAlpha*pulse;const color=isSun?'255,220,120':'180,200,240';ctx.save();for(let i=0;i<3;i++){const rippleX=reflX+Math.sin(elapsed*0.005+i*2)*4;const rippleAlpha=alpha*(1-i*0.25);const grad=ctx.createRadialGradient(rippleX,reflY+i*6,0,rippleX,reflY+i*6,(isSun?12:8)+i*5);grad.addColorStop(0,`rgba(${color},${rippleAlpha})`);grad.addColorStop(0.6,`rgba(${color},${rippleAlpha * 0.3})`);grad.addColorStop(1,`rgba(${color},0)`);ctx.fillStyle=grad;ctx.beginPath();ctx.ellipse(rippleX,reflY+i*6,(isSun?12:8)+i*3,7-i,0,0,Math.PI*2);ctx.fill();}
ctx.fillStyle=`rgba(${color},${alpha * 1.5})`;ctx.beginPath();ctx.ellipse(reflX,reflY,3,6,0,0,Math.PI*2);ctx.fill();ctx.restore();}
function _generateRain(w,h){const drops=[];for(let i=0;i<60;i++){drops.push({x:Math.random()*w*1.3-w*0.15,y:Math.random()*h,speed:400+Math.random()*200,length:8+Math.random()*12,alpha:0.15+Math.random()*0.2,});}
return drops;}
function _drawRain(ctx,drops,w,h,elapsed){const groundY=h*0.72;const dt=0.016;const windAngle=0.15;ctx.save();ctx.strokeStyle='rgba(180,190,210,0.25)';ctx.lineWidth=0.8;for(const d of drops){d.y+=d.speed*dt;d.x-=d.speed*dt*windAngle;if(d.y>groundY){const splashAlpha=0.2;ctx.fillStyle=`rgba(180,190,210,${splashAlpha})`;ctx.beginPath();ctx.ellipse(d.x,groundY+1,2,0.8,0,0,Math.PI*2);ctx.fill();d.y=-d.length-Math.random()*40;d.x=Math.random()*w*1.3-w*0.15;}
const endX=d.x+d.length*windAngle;const endY=d.y+d.length;ctx.globalAlpha=d.alpha;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(endX,endY);ctx.stroke();}
ctx.restore();}
